package com.buildertoolbox.client.events.render;import java.util.*;import net.minecraft.util.math.BlockPos;import com.buildertoolbox.client.utils.render.color.Color;import com.buildertoolbox.client.renderer.ShapeMode;public final class Render3DEvent {public final Overlay renderer=new Overlay();public static final class Overlay {public final List<Box> boxes=new ArrayList<>();public void box(BlockPos p,Color side,Color line,ShapeMode mode,int exclude){Color color=line==null?side:line;if(color!=null)boxes.add(new Box(p.toImmutable(),color.getPacked()));}}public record Box(BlockPos pos,int color){}}